function creerSubject() {
  const observers = [];
  let closed = false;
  let lastError = null;

  const subject = {
    subscribe(handlers) {
      const obs = {
        next: (typeof handlers === 'function') ? handlers : (handlers && handlers.next) || (() => {}),
        error: (handlers && handlers.error) || (() => {}),
        complete: (handlers && handlers.complete) || (() => {}),
      };
      observers.push(obs);
      return {
        unsubscribe() {
          const idx = observers.indexOf(obs);
          if (idx !== -1) observers.splice(idx, 1);
        }
      };
    },
    next(val) {
      if (closed) return;
      const snapshot = observers.slice();
      for (const o of snapshot) {
        try { o.next(val); } catch (e) {}
      }
    },
    error(err) {
      if (closed) return;
      closed = true;
      lastError = err;
      const snapshot = observers.slice();
      for (const o of snapshot) {
        try { o.error(err); } catch (e) {}
      }
      observers.length = 0;
    },
    complete() {
      if (closed) return;
      closed = true;
      const snapshot = observers.slice();
      for (const o of snapshot) {
        try { o.complete(); } catch (e) {}
      }
      observers.length = 0;
    }
  };
  return subject;
}
